namespace Panathinaikon.Api;
public sealed class Store { public int Id { get; set; } public string Name { get; set; } = ""; public string Code { get; set; } = ""; public bool IsActive { get; set; } = true; public DateTime CreatedAtUtc { get; set; } = DateTime.UtcNow; }
public sealed class UserAccount { public int Id { get; set; } public int StoreId { get; set; } public Store? Store { get; set; } public string Username { get; set; } = ""; public string DisplayName { get; set; } = ""; public string PasswordHash { get; set; } = ""; public string Role { get; set; } = "Staff"; public bool IsActive { get; set; } = true; public DateTime CreatedAtUtc { get; set; } = DateTime.UtcNow; }
public sealed class DiningTable { public int Id { get; set; } public int StoreId { get; set; } public string Name { get; set; } = ""; public int Capacity { get; set; } = 2; public string Status { get; set; } = "Available"; public bool IsActive { get; set; } = true; }
public sealed class ItemCategory { public int Id { get; set; } public int StoreId { get; set; } public string Name { get; set; } = ""; }
public sealed class SaleItem { public int Id { get; set; } public int StoreId { get; set; } public int? CategoryId { get; set; } public ItemCategory? Category { get; set; } public string Code { get; set; } = ""; public string Name { get; set; } = ""; public decimal Price { get; set; } public bool IsActive { get; set; } = true; public DateTime UpdatedAtUtc { get; set; } = DateTime.UtcNow; }
public sealed class Customer { public int Id { get; set; } public int StoreId { get; set; } public string Name { get; set; } = ""; public string? Phone { get; set; } public string? Address { get; set; } }
public sealed class SalesOrder { public int Id { get; set; } public int StoreId { get; set; } public int? TableId { get; set; } public int? CustomerId { get; set; } public Customer? Customer { get; set; } public string? Notes { get; set; } public string OrderNumber { get; set; } = ""; public string Channel { get; set; } = "Table"; public string Status { get; set; } = "Open"; public decimal Subtotal { get; set; } public decimal DiscountAmount { get; set; } public decimal Total { get; set; } public DateTime CreatedAtUtc { get; set; } = DateTime.UtcNow; public DateTime? ClosedAtUtc { get; set; } public List<SalesOrderLine> Lines { get; set; } = []; }
public sealed class SalesOrderLine { public int Id { get; set; } public int SalesOrderId { get; set; } public SalesOrder? SalesOrder { get; set; } public int SaleItemId { get; set; } public string ItemNameSnapshot { get; set; } = ""; public decimal UnitPrice { get; set; } public decimal Quantity { get; set; } public decimal LineTotal { get; set; } }
public sealed class StockItem { public int Id { get; set; } public int StoreId { get; set; } public string Code { get; set; } = ""; public string Name { get; set; } = ""; public string Category { get; set; } = ""; public string Unit { get; set; } = ""; public decimal Quantity { get; set; } public decimal MinimumQuantity { get; set; } public decimal UnitCost { get; set; } public bool IsActive { get; set; } = true; }
public sealed class StockMovement { public long Id { get; set; } public int StoreId { get; set; } public int StockItemId { get; set; } public decimal QuantityDelta { get; set; } public string MovementType { get; set; } = ""; public string? Reference { get; set; } public DateTime CreatedAtUtc { get; set; } = DateTime.UtcNow; }
public sealed class Recipe { public int Id { get; set; } public int StoreId { get; set; } public int SaleItemId { get; set; } public decimal SalePriceSnapshot { get; set; } public bool IsActive { get; set; } = true; public List<RecipeIngredient> Ingredients { get; set; } = []; }
public sealed class RecipeIngredient { public int Id { get; set; } public int RecipeId { get; set; } public int StockItemId { get; set; } public decimal Quantity { get; set; } }

public sealed class OrderPayment { public long Id { get; set; } public int StoreId { get; set; } public int SalesOrderId { get; set; } public decimal Amount { get; set; } public string Method { get; set; } = "Cash"; public string? Reference { get; set; } public DateTime PaidAtUtc { get; set; } = DateTime.UtcNow; }
